  string record=Path.Combine(records,"28987_fixture.dat");byte[] data=Encoding.UTF8.GetBytes("0000"+Common.Json.Serialize(new{wpId="28987",wpName=md5+".cwp",wpMd5=md5,wpType=2}));for(int i=0;i<data.Length;i++)data[i]^=0xe7;File.WriteAllBytes(record,data);File.WriteAllText(Path.Combine(Common.Root,"tests","import-root.txt"),fixture);
  var c=LocalImport.ReadRecord(record);var result=await ImportJob("check",c,null);c=Common.Json.Deserialize<ImportCandidate>(Common.Json.Serialize(result["candidate"]));Require(CandidateChecks.Passed(c)&&c.Check.CoverKind==PreviewCovers.Kind,"Candidate didn't reuse same-content preview image before import");Require(c.Check.CoverSha256==binding.ImageSha256&&Common.Hash(c.Cover)==binding.ImageSha256,"Candidate image binding mismatch");
  var d=new ImportDialog(this){TestSkipInitialScan=true};importDialog=d;d.Show(this);var row=d.TestAddCandidate(c);Require(d.list.SelectedItems.Count==0&&row.ImageKey!="","Unselected candidate didn't show thumbnail");Require(d.ResourceState(c)!="已入库","Isolated candidate unexpectedly imported");await d.TestRunQueue();row.Selected=true;d.UpdateSelection();await Task.Delay(180);ClientShot(d,"candidate-existing-user-picture");
  var cached=LocalImport.ReadRecord(record);Require(CandidateChecks.Load(cached,()=>{})&&cached.Check.HashedBytes==0,"Valid result didn't reuse cache");
  var unknown=new CandidateCheckResult{State="unknown",Sha256=new string('0',64)};PreviewCovers.Attach(unknown);Require(unknown.CoverRelative==null,"Unknown content inherited old image");
  Require(Directory.GetDirectories(Session,"run-*").Length==0,"Candidate inspection started renderer");Require(!library.Doc.Items.Any(x=>x.RegisteredSha256==item.RegisteredSha256),"Candidate was automatically imported");d.Close();importDialog=null;
  Common.SaveNew(Path.Combine(Common.Root,"evidence","candidate-reuse-result.json"),new{passed=true,resourceSha256=c.Check.Sha256,imageSha256=c.Check.CoverSha256,sourceType=c.Check.CoverKind,unimportedCandidate=true,unselectedThumbnail=true,fullHashCheckedInBackground=true,cacheReused=true,wrongContentNotMatched=true,renderStarted=false,autoGenerated=false,autoImported=false,userClicked=false,scope="Existing user-generated image reuse only; does not demonstrate automatic background rendering"});
 }catch(Exception ex){Common.SaveNew(Path.Combine(Common.Root,"evidence","candidate-reuse-failed.json"),new{error=ex.ToString()});}Close();}
